ipnetwork = { version = "0.21" }
libc = { version = "0.2.76", default-features = false }
log = { version = "0.4.20" }
mio = { version = "1" }
nix = { version = "0.31.3", features = ["net", "uio", "socket"] }
netlog = { version = "0.1", path="./netlog" }
octets = { version = "0.3.7", path = "./octets" }
parking_lot = { version = "0.12.1", default-features = false }
pin-project = { version = "1.0.12" }
qlog = { version = "0.18.0", path = "./qlog" }
quiche = { version = "0.30.0", path = "./quiche" }
regex = { version = "1.4.2" }
